1	package server
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/url"
9		"regexp"
10		"time"
11		"unicode/utf8"
12	)
13	
14	// leaseHeader carries the lease token on heartbeat and deregister requests.
15	const leaseHeader = "X-Meshcore-Lease"
16	
17	// namePattern constrains service and instance names: 1-64 ASCII letters,
18	// digits, dots, underscores or hyphens.
19	var namePattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)
20	
21	func validName(s string) bool { return namePattern.MatchString(s) }
22	
23	type registerRequest struct {
24		Endpoint   string            `json:"endpoint"`
25		Version    string            `json:"version"`
26		Zone       string            `json:"zone"`
27		Weight     int               `json:"weight"`
28		TTLSeconds int               `json:"ttlSeconds"`
29		Metadata   map[string]string `json:"metadata"`
30	}
31	
32	func (r *registerRequest) valid() bool {
33		if r.Endpoint == "" || r.Version == "" || r.Zone == "" {
34			return false
35		}
36		if r.Weight < 1 || r.Weight > 100 || r.TTLSeconds < 1 || r.TTLSeconds > 300 {
37			return false
38		}
39		for k, v := range r.Metadata {
40			if k == "" || v == "" {
41				return false
42			}
43		}
44		return true
45	}
46	
47	// instanceView is the public representation of a registered instance. The
48	// lease token is deliberately excluded; it only appears in registerResponse.
49	type instanceView struct {
50		Service    string            `json:"service"`
51		Instance   string            `json:"instance"`
52		Endpoint   string            `json:"endpoint"`
53		Version    string            `json:"version"`
54		Zone       string            `json:"zone"`
55		Weight     int               `json:"weight"`
56		TTLSeconds int               `json:"ttlSeconds"`
57		Metadata   map[string]string `json:"metadata"`
58		ExpiresAt  string            `json:"expiresAt"`
59	}
60	
61	func viewOf(inst instance) instanceView {
62		return instanceView{
63			Service:    inst.Service,
64			Instance:   inst.Instance,
65			Endpoint:   inst.Endpoint,
66			Version:    inst.Version,
67			Zone:       inst.Zone,
68			Weight:     inst.Weight,
69			TTLSeconds: inst.TTLSeconds,
70			Metadata:   inst.Metadata,
71			ExpiresAt:  inst.expiresAt.UTC().Format(time.RFC3339),
72		}
73	}
74	
75	type registerResponse struct {
76		instanceView
77		LeaseToken string `json:"leaseToken"`
78	}
79	
80	type discoveryResponse struct {
81		Service   string         `json:"service"`
82		Instances []instanceView `json:"instances"`
83	}
84	
85	type resolveResponse struct {
86		Service  string       `json:"service"`
87		Key      string       `json:"key"`
88		Instance instanceView `json:"instance"`
89	}
90	
91	func writeJSON(w http.ResponseWriter, status int, v any) {
92		w.Header().Set("Content-Type", "application/json; charset=utf-8")
93		w.WriteHeader(status)
94		_ = json.NewEncoder(w).Encode(v)
95	}
96	
97	func writeError(w http.ResponseWriter, status int, code string) {
98		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
99	}
100	
101	// handleInstance serves /v1/services/{service}/instances/{instance}.
102	func (s *server) handleInstance(w http.ResponseWriter, r *http.Request) {
103		switch r.Method {
104		case http.MethodPut:
105			s.register(w, r)
106		case http.MethodDelete:
107			s.deregister(w, r)
108		default:
109			w.Header().Set("Allow", "PUT, DELETE")
110			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
111		}
112	}
113	
114	func (s *server) register(w http.ResponseWriter, r *http.Request) {
115		service, name := r.PathValue("service"), r.PathValue("instance")
116		if !validName(service) || !validName(name) {
117			writeError(w, http.StatusBadRequest, "validation_error")
118			return
119		}
120		var req registerRequest
121		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
122		dec.DisallowUnknownFields()
123		if err := dec.Decode(&req); err != nil || dec.Decode(&struct{}{}) != io.EOF || !req.valid() {
124			writeError(w, http.StatusBadRequest, "validation_error")
125			return
126		}
127		metadata := make(map[string]string, len(req.Metadata))
128		for k, v := range req.Metadata {
129			metadata[k] = v
130		}
131		inst := &instance{
132			Service:    service,
133			Instance:   name,
134			Endpoint:   req.Endpoint,
135			Version:    req.Version,
136			Zone:       req.Zone,
137			Weight:     req.Weight,
138			TTLSeconds: req.TTLSeconds,
139			Metadata:   metadata,
140		}
141		stored, overwritten := s.registry.register(inst, s.now())
142		status := http.StatusCreated
143		if overwritten {
144			status = http.StatusOK
145		}
146		writeJSON(w, status, registerResponse{instanceView: viewOf(stored), LeaseToken: stored.token})
147	}
148	
149	func (s *server) deregister(w http.ResponseWriter, r *http.Request) {
150		service, name := r.PathValue("service"), r.PathValue("instance")
151		if !validName(service) || !validName(name) {
152			writeError(w, http.StatusBadRequest, "validation_error")
153			return
154		}
155		err := s.registry.deregister(service, name, r.Header.Get(leaseHeader), s.now())
156		writeLeaseResult(w, err)
157	}
158	
159	// handleHeartbeat serves /v1/services/{service}/instances/{instance}/heartbeat.
160	func (s *server) handleHeartbeat(w http.ResponseWriter, r *http.Request) {
161		if r.Method != http.MethodPost {
162			w.Header().Set("Allow", http.MethodPost)
163			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
164			return
165		}
166		service, name := r.PathValue("service"), r.PathValue("instance")
167		if !validName(service) || !validName(name) {
168			writeError(w, http.StatusBadRequest, "validation_error")
169			return
170		}
171		err := s.registry.renew(service, name, r.Header.Get(leaseHeader), s.now())
172		writeLeaseResult(w, err)
173	}
174	
175	func writeLeaseResult(w http.ResponseWriter, err error) {
176		switch {
177		case err == nil:
178			w.WriteHeader(http.StatusNoContent)
179		case errors.Is(err, errNotFound):
180			writeError(w, http.StatusNotFound, "instance_not_found")
181		case errors.Is(err, errLeaseConflict):
182			writeError(w, http.StatusConflict, "lease_conflict")
183		default:
184			writeError(w, http.StatusInternalServerError, "internal_error")
185		}
186	}
187	
188	// handleDiscovery serves /v1/discovery/{service}.
189	func (s *server) handleDiscovery(w http.ResponseWriter, r *http.Request) {
190		if r.Method != http.MethodGet {
191			w.Header().Set("Allow", http.MethodGet)
192			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
193			return
194		}
195		service := r.PathValue("service")
196		if !validName(service) {
197			writeError(w, http.StatusBadRequest, "validation_error")
198			return
199		}
200		query, err := url.ParseQuery(r.URL.RawQuery)
201		if err != nil {
202			writeError(w, http.StatusBadRequest, "validation_error")
203			return
204		}
205		var version, zone string
206		for key, values := range query {
207			if (key != "version" && key != "zone") || len(values) != 1 || values[0] == "" {
208				writeError(w, http.StatusBadRequest, "validation_error")
209				return
210			}
211			if key == "version" {
212				version = values[0]
213			} else {
214				zone = values[0]
215			}
216		}
217		instances := s.registry.snapshot(service, version, zone, s.now())
218		views := make([]instanceView, 0, len(instances))
219		for _, inst := range instances {
220			views = append(views, viewOf(inst))
221		}
222		writeJSON(w, http.StatusOK, discoveryResponse{Service: service, Instances: views})
223	}
224	
225	// maxKeyBytes bounds the URL-decoded routing key accepted by handleResolve.
226	const maxKeyBytes = 256
227	
228	// handleResolve serves /v1/resolve/{service}: it maps the caller's routing
229	// key onto a single live instance via consistent hashing. The selection is
230	// computed from the current snapshot only; it never creates or extends a
231	// lease.
232	func (s *server) handleResolve(w http.ResponseWriter, r *http.Request) {
233		if r.Method != http.MethodGet {
234			w.Header().Set("Allow", http.MethodGet)
235			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
236			return
237		}
238		service := r.PathValue("service")
239		if !validName(service) {
240			writeError(w, http.StatusBadRequest, "validation_error")
241			return
242		}
243		query, err := url.ParseQuery(r.URL.RawQuery)
244		if err != nil {
245			writeError(w, http.StatusBadRequest, "validation_error")
246			return
247		}
248		var key, version, zone string
249		for param, values := range query {
250			if len(values) != 1 || values[0] == "" {
251				writeError(w, http.StatusBadRequest, "validation_error")
252				return
253			}
254			switch param {
255			case "key":
256				key = values[0]
257			case "version":
258				version = values[0]
259			case "zone":
260				zone = values[0]
261			default:
262				writeError(w, http.StatusBadRequest, "validation_error")
263				return
264			}
265		}
266		if key == "" || len(key) > maxKeyBytes || !utf8.ValidString(key) {
267			writeError(w, http.StatusBadRequest, "validation_error")
268			return
269		}
270		instances := s.registry.snapshot(service, version, zone, s.now())
271		chosen, ok := selectInstance(key, instances)
272		if !ok {
273			writeError(w, http.StatusServiceUnavailable, "no_available_instance")
274			return
275		}
276		writeJSON(w, http.StatusOK, resolveResponse{Service: service, Key: key, Instance: viewOf(chosen)})
277	}
