	case err == nil:
		w.WriteHeader(http.StatusNoContent)
	case errors.Is(err, errNotFound):
		writeError(w, http.StatusNotFound, "instance_not_found")
	case errors.Is(err, errLeaseConflict):
		writeError(w, http.StatusConflict, "lease_conflict")
	default:
		writeError(w, http.StatusInternalServerError, "internal_error")
	}
}

// handleDiscovery serves /v1/discovery/{service}.
func (s *server) handleDiscovery(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	service := r.PathValue("service")
	if !validName(service) {
		writeError(w, http.StatusBadRequest, "validation_error")
		return
	}
	query, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil {
		writeError(w, http.StatusBadRequest, "validation_error")
		return
	}
	var version, zone string
	for key, values := range query {
		if (key != "version" && key != "zone") || len(values) != 1 || values[0] == "" {
			writeError(w, http.StatusBadRequest, "validation_error")
			return
		}
		if key == "version" {
			version = values[0]
		} else {
			zone = values[0]
		}
	}
	instances := s.registry.snapshot(service, version, zone, s.now())
	views := make([]instanceView, 0, len(instances))
	for _, inst := range instances {
		views = append(views, viewOf(inst))
	}
	writeJSON(w, http.StatusOK, discoveryResponse{Service: service, Instances: views})
}

// maxKeyBytes bounds the URL-decoded routing key accepted by handleResolve.
const maxKeyBytes = 256

// handleResolve serves /v1/resolve/{service}: it maps the caller's routing
// key onto a single live instance via consistent hashing. The selection is
// computed from the current snapshot only; it never creates or extends a
// lease.
func (s *server) handleResolve(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	service := r.PathValue("service")
	if !validName(service) {
		writeError(w, http.StatusBadRequest, "validation_error")
		return
	}
	query, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil {
		writeError(w, http.StatusBadRequest, "validation_error")
		return
	}
	var key, version, zone string
	for param, values := range query {
		if len(values) != 1 || values[0] == "" {
			writeError(w, http.StatusBadRequest, "validation_error")
			return
		}
		switch param {
		case "key":
			key = values[0]
		case "version":
			version = values[0]
		case "zone":
			zone = values[0]
		default:
			writeError(w, http.StatusBadRequest, "validation_error")
			return
		}
	}
	if key == "" || len(key) > maxKeyBytes || !utf8.ValidString(key) {
		writeError(w, http.StatusBadRequest, "validation_error")
		return
	}
	instances := s.registry.snapshot(service, version, zone, s.now())
	chosen, ok := selectInstance(key, instances)
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "no_available_instance")
		return
	}
	writeJSON(w, http.StatusOK, resolveResponse{Service: service, Key: key, Instance: viewOf(chosen)})
}

// Package server exposes the public HTTP surface of MeshCore.
//
// Besides process health, the surface covers in-process service registration,
// lease renewal, deregistration and discovery. Registrations live in memory
// only: a process restart starts from an empty registry.
package server

import (
	"encoding/json"
	"net/http"
	"time"
)

// Version is the baseline release identifier.
const Version = "0.1.0"

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// server bundles the registry with a clock so tests can control expiration.
type server struct {
	registry *registry
	now      func() time.Time
}

func newServer() *server {
	return &server{registry: newRegistry(), now: time.Now}
}

// Handler returns the HTTP surface served by MeshCore.
func Handler() http.Handler {
	return newServer().handler()
}

func (s *server) handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "meshcore", Version: Version})
	})
	mux.HandleFunc("/v1/services/{service}/instances/{instance}", s.handleInstance)
	mux.HandleFunc("/v1/services/{service}/instances/{instance}/heartbeat", s.handleHeartbeat)
	mux.HandleFunc("/v1/discovery/{service}", s.handleDiscovery)
	mux.HandleFunc("/v1/resolve/{service}", s.handleResolve)
	return mux
}

